package fileutil

import (
	"io/ioutil"
	"os"
)

func ReadText(path string) (string, error) {
	data, err := ioutil.ReadFile(path)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func WriteText(path, content string) error {
	return ioutil.WriteFile(path, []byte(content), 0644)
}

func TempFile(dir, pattern string) (*os.File, error) {
	return ioutil.TempFile(dir, pattern)
}

package fileutil

import (
	"os"
	"testing"
)

func TestReadWrite(t *testing.T) {
	f, err := TempFile("", "test")
	if err != nil {
		t.Fatal(err)
	}
	defer os.Remove(f.Name())
	f.Close()

	err = WriteText(f.Name(), "hello world")
	if err != nil {
		t.Fatal(err)
	}

	got, err := ReadText(f.Name())
	if err != nil {
		t.Fatal(err)
	}
	if got != "hello world" {
		t.Fatalf("want 'hello world' got %q", got)
	}
}

func TestReadMissing(t *testing.T) {
	_, err := ReadText("/nonexistent/path/file.txt")
	if err == nil {
		t.Fatal("expected error for missing file")
	}
}

func TestWriteAndRead(t *testing.T) {
	f, err := TempFile("", "rw")
	if err != nil {
		t.Fatal(err)
	}
	defer os.Remove(f.Name())
	f.Close()
	if err := WriteText(f.Name(), "data"); err != nil {
		t.Fatal(err)
	}
	got, _ := ReadText(f.Name())
	if got != "data" {
		t.Fatalf("want data got %q", got)
	}
}

func TestTempFile(t *testing.T) {
	f, err := TempFile("", "prefix")
	if err != nil {
		t.Fatal(err)
	}
	defer os.Remove(f.Name())
	f.Close()
}

func TestWriteEmpty(t *testing.T) {
	f, _ := TempFile("", "empty")
	defer os.Remove(f.Name())
	f.Close()
	WriteText(f.Name(), "")
	got, _ := ReadText(f.Name())
	if got != "" {
		t.Fatalf("want empty got %q", got)
	}
}
